      confidence: geminiResult.confidence,
      diseaseName: geminiResult.diseaseName || details2.name,
      scientificName: geminiResult.scientificName || details2.scientificName,
      description: geminiResult.description || details2.description,
      symptoms: Array.isArray(geminiResult.symptoms) ? geminiResult.symptoms : details2.symptoms,
      organicTreatment: Array.isArray(geminiResult.organicTreatment) ? geminiResult.organicTreatment : details2.organicTreatment,
      chemicalTreatment: Array.isArray(geminiResult.chemicalTreatment) ? geminiResult.chemicalTreatment : details2.chemicalTreatment,
      applicationSteps: Array.isArray(geminiResult.applicationSteps) ? geminiResult.applicationSteps : details2.applicationSteps,
      safetyPrecautions: Array.isArray(geminiResult.safetyPrecautions) ? geminiResult.safetyPrecautions : details2.safetyPrecautions,
