          cropRotation: details2.cropRotation,
          waterManagement: details2.waterManagement,
          soilHealth: details2.soilHealth,
          spacingTechniques: details2.spacingTechniques,
          resistantVarieties: details2.resistantVarieties,
          toolSanitation: details2.toolSanitation,
          seasonalPrecautions: details2.seasonalPrecautions,
